{
  "findings": [
    {
      "check_id": "CKV_AZURE_115",
      "title": "MySQL server does not have geo-redundant backup enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "HIGH",
      "explanation": "Geo-redundant backups ensure that data is replicated across regions, providing resilience against regional failures. This configuration is missing in the MySQL server."
    },
    {
      "check_id": "CKV_AZURE_116",
      "title": "MySQL server does not have minimum TLS version enforced",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "HIGH",
      "explanation": "Enforcing a minimum TLS version (e.g., TLS 1.2) ensures secure communication between clients and the database server. The current configuration does not specify a minimum TLS version."
    }
  ],
  "patched_code": "resource \"azurerm_mysql_server\" \"changeme_simple_mysql_server\" {\n  name                = \"changeme-simple-mysql-database-name\"\n  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name\n  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location\n  storage_mb          = \"5120\"\n  sku_name            = \"B_Gen5_1\"\n  version             = \"8.0\"\n  administrator_login = \"changemeadmin\"\n  administrator_login_password = \"ch4ng3m3-A@Â£$%^&\"\n  ssl_enforcement_enabled      = true\n  backup_retention_days        = 7\n  geo_redundant_backup_enabled = true\n  minimal_tls_version          = \"TLS1_2\"\n}",
  "fix_summary": "Enabled geo-redundant backups and enforced a minimum TLS version of TLS 1.2 for the MySQL server to enhance data resilience and secure communication."
}
